<?php
declare(strict_types=1);
namespace App\Services\Finance;
use App\Models\Finance\{StudentInvoice,StudentInvoiceItem}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class InvoiceService {public function save(array $data,?StudentInvoice $invoice=null,int|null $actor=null):StudentInvoice{return DB::transaction(function()use($data,$invoice,$actor){$amount=(string)$data['amount'];$invoice??=new StudentInvoice;$paid=(string)($invoice->paid_amount??0);$out=(string)max(0,(int)$amount-(int)$paid);$status=(int)$paid>0?((int)$out===0?'paid':'partial'):(now()->toDateString()>$data['due_date']?'overdue':'open');$invoice->fill(['student_id'=>$data['student_id'],'academic_year_id'=>$data['academic_year_id'],'semester_id'=>$data['semester_id']??null,'invoice_number'=>$invoice->invoice_number?:'INV-'.now()->format('Ymd').'-'.Str::upper(Str::random(8)),'billing_month'=>$data['billing_month'].'-01','issue_date'=>$data['issue_date'],'due_date'=>$data['due_date'],'subtotal'=>$amount,'total'=>$amount,'paid_amount'=>$paid,'outstanding_amount'=>$out,'status'=>$status,'created_by'=>$invoice->created_by?:$actor])->save();StudentInvoiceItem::updateOrCreate(['invoice_id'=>$invoice->id],['fee_type_id'=>$data['fee_type_id'],'description'=>$data['description']??'Tagihan siswa','qty'=>1,'unit_amount'=>$amount,'amount'=>$amount]);return $invoice;});}public function cancel(StudentInvoice $invoice,int $actor):void{abort_if($invoice->status==='paid',422,'Tagihan lunas tidak dapat dibatalkan.');$invoice->update(['status'=>'cancelled','cancelled_by'=>$actor,'cancelled_at'=>now()]);}}
